def topo_sort(graph):
    in_degree = {node: 0 for node in graph}
    for node, prereqs in graph.items():
        for prereq in prereqs:
            if prereq not in in_degree:
                in_degree[prereq] = 0
            in_degree[node] = in_degree.get(node, 0)
            in_degree[prereq] = in_degree.get(prereq, 0)

    # Count actual prerequisites
    in_degree = {node: len(graph.get(node, [])) for node in graph}
    for node, prereqs in graph.items():
        for prereq in prereqs:
            if prereq not in graph:
                in_degree[prereq] = 0

    # Ensure all nodes are in in_degree
    all_nodes = set(graph.keys())
    for prereqs in graph.values():
        all_nodes.update(prereqs)
    for node in all_nodes:
        if node not in in_degree:
            in_degree[node] = 0

    # Find nodes with no prerequisites
    ready = sorted([node for node in in_degree if in_degree[node] == 0])
    result = []
    while ready:
        node = ready.pop(0)
        result.append(node)
        # Find all dependents of this node
        for other, prereqs in graph.items():
            if node in prereqs:
                in_degree[other] -= 1
                if in_degree[other] == 0:
                    # Insert in sorted order to maintain lexicographic order
                    import bisect
                    bisect.insort(ready, other)
    # Check for cycles
    if len(result) != len(all_nodes):
        raise ValueError("Cycle detected in graph")
    return result
